final class GameService {
    private PDO $pdo;
    public function __construct(?PDO $pdo = null) { $this->pdo = $pdo ?? db() ?? throw new RuntimeException('Database unavailable'); }
    private function setting(string $key, int $fallback): int { $stmt=$this->pdo->prepare('SELECT setting_value FROM game_settings WHERE setting_key=?'); $stmt->execute([$key]); $value=$stmt->fetchColumn(); return $value !== false ? (int)$value : $fallback; }
    private function resources(int $playerId, bool $lock = false): array {
        $sql='SELECT * FROM player_resources WHERE player_id=?' . ($lock ? ' FOR UPDATE' : ''); $stmt=$this->pdo->prepare($sql); $stmt->execute([$playerId]); $row=$stmt->fetch(); if (!$row) throw new RuntimeException('Player resources not found'); return $row;
    }
    private function player(int $playerId, bool $lock = false): array {
        $sql='SELECT p.*,r.name AS race FROM players p JOIN races r ON r.id=p.race_id WHERE p.id=?' . ($lock ? ' FOR UPDATE' : ''); $stmt=$this->pdo->prepare($sql); $stmt->execute([$playerId]); $row=$stmt->fetch(); if (!$row) throw new RuntimeException('Player not found'); return $row;
    }
    private function event(int $playerId, string $type, ?string $entityType, ?int $entityId, array $payload): void { $stmt=$this->pdo->prepare('INSERT INTO game_events (player_id,event_type,entity_type,entity_id,payload) VALUES (?,?,?,?,?)'); $stmt->execute([$playerId,$type,$entityType,$entityId,json_encode($payload,JSON_THROW_ON_ERROR)]); }
    public function processTurns(int $playerId, ?DateTimeImmutable $now=null): array {
        $now=$now ?? new DateTimeImmutable('now');
        $this->pdo->beginTransaction();
        try {
            $player=$this->player($playerId,true);
            $resources=$this->resources($playerId,true);
            $interval=$this->setting('turn_interval_seconds',1800);
            $threshold=$this->setting('turn_generation_threshold',4000);
            $max=$this->setting('turn_max_storage',10000);
            $last=$player['last_turn_at'] ? new DateTimeImmutable($player['last_turn_at']) : $now;
            $elapsed=max(0,$now->getTimestamp()-$last->getTimestamp());
            $due=intdiv($elapsed,$interval);
            if($due<1){$this->pdo->commit();return ['turns'=>0,'income'=>0,'elapsed_seconds'=>$elapsed];}
            $currentTurns=(int)$resources['attack_turns'];
            $turns=min($due,max(0,$max-$currentTurns));
            $generationApplied=$currentTurns<$threshold;
            $newUnits=$generationApplied?(int)$resources['unit_production']*$due:0;
            $baseIncome=((int)$resources['untrained_units']*20)+(((int)$resources['miners']+(int)$resources['lifers'])*80);
            $income=$generationApplied?$baseIncome*$due:0;
            $raceMultiplier=$player['race']==='Goa\'uld'?1.25:1.0;
            $defconMultiplier=[0=>1.0,1=>.90,2=>.80,3=>.60,4=>.30][(int)$player['defcon_level']]??1.0;
            $income=(int)round($income*$raceMultiplier*$defconMultiplier);
            $this->pdo->prepare('UPDATE player_resources SET attack_turns=LEAST(?,attack_turns+?),untrained_units=untrained_units+?,naquadah=naquadah+? WHERE player_id=?')->execute([$max,$turns,$newUnits,$income,$playerId]);
            $newLast=$last->modify('+'.($due*$interval).' seconds')->format('Y-m-d H:i:s');
            $this->pdo->prepare('UPDATE players SET last_turn_at=? WHERE id=?')->execute([$newLast,$playerId]);
            $this->event($playerId,'turn_processed',null,null,['turns'=>$turns,'due_intervals'=>$due,'income'=>$income,'untrained_units'=>$newUnits,'generation_applied'=>$generationApplied]);
            $this->pdo->commit();
            $colonySettlement=(new EconomyService($this->pdo))->settlePlayerColonies($playerId,$due);
            return ['turns'=>$turns,'income'=>$income,'due_intervals'=>$due,'untrained_units'=>$newUnits,'elapsed_seconds'=>$elapsed,'colony_settlement'=>$colonySettlement];
        } catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function deposit(int $playerId,int $amount):void{$this->moveBank($playerId,$amount,true);}
    public function withdraw(int $playerId,int $amount):void{$this->moveBank($playerId,$amount,false);}
    private function moveBank(int $playerId,int $amount,bool $deposit):void{if($playerId<1)throw new InvalidArgumentException('Invalid commander');if($amount<1)throw new InvalidArgumentException('Amount must be positive');$this->pdo->beginTransaction();try{$r=$this->resources($playerId,true);$cooldownSeconds=$this->setting('bank_transfer_cooldown_seconds',0);$cooldownStmt=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='bank_transfer' FOR UPDATE");$cooldownStmt->execute([$playerId]);$availableAt=$cooldownStmt->fetchColumn();if($availableAt!==false&&new DateTimeImmutable((string)$availableAt)>new DateTimeImmutable('now'))throw new RuntimeException('Vault transfer is on cooldown.');if($deposit){if((int)$r['naquadah']<$amount)throw new RuntimeException('Not enough available Naquadah');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-?,banked_naquadah=banked_naquadah+? WHERE player_id=?')->execute([$amount,$amount,$playerId]);}else{if((int)$r['banked_naquadah']<$amount)throw new RuntimeException('Not enough banked Naquadah');$this->pdo->prepare('UPDATE player_resources SET banked_naquadah=banked_naquadah-?,naquadah=naquadah+? WHERE player_id=?')->execute([$amount,$amount,$playerId]);}if($cooldownSeconds>0){$next=(new DateTimeImmutable('now'))->modify('+'.$cooldownSeconds.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,'bank_transfer',$next]);}$this->event($playerId,$deposit?'naquadah_deposited':'naquadah_withdrawn','player_resources',$playerId,['amount'=>$amount,'cooldown_seconds'=>$cooldownSeconds]);$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function changeRace(int $playerId,int $raceId):void{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT name FROM races WHERE id=?');$s->execute([$raceId]);if(!$s->fetch())throw new RuntimeException('Race not found');$this->pdo->prepare('UPDATE players SET race_id=? WHERE id=?')->execute([$raceId,$playerId]);$this->event($playerId,'race_changed','race',$raceId,['race_id'=>$raceId]);$this->pdo->commit();}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
    public function train(int $playerId,string $type,int $quantity): void {
        if ($quantity<1) throw new InvalidArgumentException('Quantity must be positive'); $allowed=['miners','attack_units','defense_units','spies','anti_spies']; if(!in_array($type,$allowed,true)) throw new InvalidArgumentException('Invalid training type');
        $this->pdo->beginTransaction(); try{$r=$this->resources($playerId,true);if((int)$r['untrained_units']<$quantity)throw new RuntimeException('Not enough untrained units');$this->pdo->prepare("UPDATE player_resources SET untrained_units=untrained_units-?,{$type}={$type}+? WHERE player_id=?")->execute([$quantity,$quantity,$playerId]);$this->event($playerId,'units_trained','player_resources', $playerId,['type'=>$type,'quantity'=>$quantity]);$this->pdo->commit();}catch(Throwable $e){$this->pdo->rollBack();throw $e;}
    }
    public function upgradeUnitProduction(int $playerId): int {
        $this->pdo->beginTransaction(); try{$r=$this->resources($playerId,true);$cost=((int)$r['unit_production']*5000)+10000;if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-?,unit_production=unit_production+1 WHERE player_id=?')->execute([$cost,$playerId]);$this->event($playerId,'unit_production_upgraded','player_resources',$playerId,['cost'=>$cost]);$this->pdo->commit();return $cost;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}
    }
    public function buyTechnology(int $playerId,string $key): int {
        $this->pdo->beginTransaction(); try{$stmt=$this->pdo->prepare('SELECT * FROM technologies WHERE technology_key=? FOR UPDATE');$stmt->execute([$key]);$tech=$stmt->fetch();if(!$tech)throw new RuntimeException('Technology not found');$stmt=$this->pdo->prepare('SELECT * FROM player_technologies WHERE player_id=? AND technology_key=? FOR UPDATE');$stmt->execute([$playerId,$key]);$owned=$stmt->fetch();$level=(int)($owned['level']??0);$cost=(int)round((int)$tech['base_cost']*pow((float)$tech['cost_growth'],$level));$r=$this->resources($playerId,true);if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah');if($owned)$this->pdo->prepare('UPDATE player_technologies SET level=level+1,next_cost=? WHERE id=?')->execute([$cost,$owned['id']]);else$this->pdo->prepare('INSERT INTO player_technologies (player_id,technology_key,technology_name,category,level,next_cost,technology_id) VALUES (?,?,?,?,?,?,?)')->execute([$playerId,$key,$tech['name'],$tech['category'],1,$cost,$tech['id']]);$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$this->event($playerId,'technology_upgraded','technology',$tech['id'],['key'=>$key,'level'=>$level+1,'cost'=>$cost]);$this->pdo->commit();return $cost;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}
    }
    public function buyWeapon(int $playerId,int $weaponTypeId,int $quantity):void{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT price,max_durability FROM weapon_types WHERE id=?');$s->execute([$weaponTypeId]);$weapon=$s->fetch();if(!$weapon||$quantity<1)throw new RuntimeException('Weapon not found');$cost=(int)$weapon['price']*$quantity;$r=$this->resources($playerId,true);if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$this->pdo->prepare('INSERT INTO player_weapons(player_id,weapon_type_id,quantity,durability) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),durability=VALUES(durability)')->execute([$playerId,$weaponTypeId,$quantity,$weapon['max_durability']]);$this->event($playerId,'weapon_purchased','weapon_type',$weaponTypeId,['quantity'=>$quantity,'cost'=>$cost]);$this->pdo->commit();}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
    public function repairWeapons(int $playerId,int $weaponId):void{$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT pw.quantity,pw.durability,wt.max_durability FROM player_weapons pw JOIN weapon_types wt ON wt.id=pw.weapon_type_id WHERE pw.id=? AND pw.player_id=? FOR UPDATE');$s->execute([$weaponId,$playerId]);$w=$s->fetch();if(!$w)throw new RuntimeException('Weapon inventory not found');$damage=max(0,(int)$w['max_durability']-(int)$w['durability']);$cost=$damage*10;$r=$this->resources($playerId,true);if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$this->pdo->prepare('UPDATE player_weapons SET durability=? WHERE id=?')->execute([(int)$w['max_durability'],$weaponId]);$this->event($playerId,'weapons_repaired','player_weapons',$weaponId,['cost'=>$cost]);$this->pdo->commit();}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
    public function upgradeMothership(int $playerId,string $module):int{$allowed=['hull_level','volley_bays','shield_bays','fleet_hangars','weapons_power','shields_power','exploration_level'];if(!in_array($module,$allowed,true))throw new InvalidArgumentException('Invalid mothership module');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare('SELECT * FROM motherships WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);$ship=$s->fetch();if(!$ship)throw new RuntimeException('Mothership not found');$current=(int)$ship[$module];$cost=25000+($current*10000);$r=$this->resources($playerId,true);if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-? WHERE player_id=?')->execute([$cost,$playerId]);$this->pdo->prepare("UPDATE motherships SET {$module}={$module}+1 WHERE player_id=?")->execute([$playerId]);$this->event($playerId,'mothership_upgraded','mothership',$ship['id'],['module'=>$module,'cost'=>$cost]);$this->pdo->commit();return $cost;}catch(Throwable $e){$this->pdo->rollBack();throw $e;}}
    public function militaryStats(int $playerId): array {
        if ($playerId < 1) throw new InvalidArgumentException('Invalid military statistics request');
        $s=$this->pdo->prepare('SELECT p.defcon_level,p.protected_until,p.vacation_until,ps.protected_until AS state_protected_until,ps.vacation_until AS state_vacation_until,r.name race_name,r.attack_modifier race_attack,r.defense_modifier race_defense,r.covert_modifier race_covert,g.name government_name,g.military_modifier government_military,g.defense_modifier government_defense,g.covert_modifier government_covert FROM players p JOIN races r ON r.id=p.race_id LEFT JOIN government_types g ON g.id=p.government_id LEFT JOIN protection_states ps ON ps.player_id=p.id WHERE p.id=?');
        $s->execute([$playerId]);$identity=$s->fetch(PDO::FETCH_ASSOC);if(!$identity)throw new RuntimeException('Player not found');
        $s=$this->pdo->prepare('SELECT * FROM player_resources WHERE player_id=?');$s->execute([$playerId]);$resources=$s->fetch(PDO::FETCH_ASSOC)?:[];
        $s=$this->pdo->prepare('SELECT * FROM player_unit_stats WHERE player_id=?');$s->execute([$playerId]);$units=$s->fetch(PDO::FETCH_ASSOC)?:[];
        $attackBase=((int)($resources['attack_units']??0)*5)+((int)($resources['super_attack_units']??0)*10)+(int)($units['attack_power']??0);
        $defenseBase=((int)($resources['defense_units']??0)*5)+((int)($resources['super_defense_units']??0)*10)+(int)($units['defense_power']??0);
        $covertBase=((int)($resources['spies']??0)*max(1,(int)($units['covert_level']??1)))+(int)($units['covert_power']??0);
        $antiCovertBase=((int)($resources['anti_spies']??0)*max(1,(int)($units['anti_covert_level']??1)))+(int)($units['anti_covert_power']??0);
        $attack=(int)round($attackBase*(float)($identity['race_attack']??1)*(float)($identity['government_military']??1));
        $defense=(int)round($defenseBase*(float)($identity['race_defense']??1)*(float)($identity['government_defense']??1));
        $covert=(int)round($covertBase*(float)($identity['race_covert']??1)*(float)($identity['government_covert']??1));
        $anti=(int)round($antiCovertBase*(float)($identity['race_covert']??1)*(float)($identity['government_covert']??1));
        $turns=(int)($resources['attack_turns']??0);$readiness=min(100,(int)round($turns/48*100));
        $cooldown=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='defcon_change'");$cooldown->execute([$playerId]);$availableAt=$cooldown->fetchColumn();$cooldownState=self::defconCooldownState($availableAt===false?null:(string)$availableAt);
        $now=new DateTimeImmutable('now');
        $protectedState=(($identity['protected_until']??null)&&new DateTimeImmutable((string)$identity['protected_until'])>$now)||(($identity['vacation_until']??null)&&new DateTimeImmutable((string)$identity['vacation_until'])>$now)||(($identity['state_protected_until']??null)&&new DateTimeImmutable((string)$identity['state_protected_until'])>$now)||(($identity['state_vacation_until']??null)&&new DateTimeImmutable((string)$identity['state_vacation_until'])>$now)?'protected':'ready';
        return ['attack_power'=>$attack,'defense_power'=>$defense,'covert_power'=>$covert,'anti_covert_power'=>$anti,'attack_base'=>$attackBase,'defense_base'=>$defenseBase,'covert_base'=>$covertBase,'anti_covert_base'=>$antiCovertBase,'attack_turns'=>$turns,'readiness'=>$readiness,'defcon_level'=>(int)($identity['defcon_level']??0),'cooldown_state'=>$cooldownState['state'],'cooldown_remaining_seconds'=>$cooldownState['remaining_seconds'],'protection_state'=>$protectedState,'race_name'=>$identity['race_name'],'government_name'=>$identity['government_name']??'Unassigned','formula'=>'power = units × base power × technology × race × government × planet bonus'];
    }
    public function targetBoard(int $playerId): array {
        if ($playerId < 1) throw new InvalidArgumentException('Invalid target-board request');
        $sql="SELECT tr.id,tr.player_id,tr.name,tr.race_name,tr.rank_position,tr.attack_score,tr.defense_score,tr.covert_score,COALESCE(tr.protection_until,p.protected_until,ps.protected_until,p.vacation_until,ps.vacation_until) protected_until FROM target_realms tr LEFT JOIN players p ON p.id=tr.player_id LEFT JOIN protection_states ps ON ps.player_id=tr.player_id WHERE tr.player_id IS NULL OR tr.player_id<>? ORDER BY tr.rank_position,tr.id";
        $s=$this->pdo->prepare($sql);$s->execute([$playerId]);$now=new DateTimeImmutable('now');$rows=[];
        foreach($s->fetchAll(PDO::FETCH_ASSOC) as $row){$protected=$row['protected_until']!==null&&new DateTimeImmutable((string)$row['protected_until'])>$now;$rows[]=['id'=>(int)$row['id'],'name'=>$row['name'],'race'=>$row['race_name'],'rank'=>(int)$row['rank_position'],'attack'=>(int)$row['attack_score'],'defense'=>(int)$row['defense_score'],'covert'=>(int)$row['covert_score'],'status'=>$protected?'PROTECTED':'OPEN','protected_until'=>$row['protected_until']];}
        return $rows;
    }
    public function combatPreview(int $playerId,int $targetId,string $action='attack',int $turns=1): array {
        if(!in_array($action,['attack','raid'],true)||$turns<1||$turns>15)throw new InvalidArgumentException('Invalid combat preview');
        $targets=$this->targetBoard($playerId);$target=null;foreach($targets as $row){if($row['id']===$targetId){$target=$row;break;}}
        if(!$target)throw new RuntimeException('Target unavailable or owned by commander');
        $r=$this->resources($playerId);$attackForce=((int)$r['attack_units']*5)+(int)$r['spies'];$defenseForce=(int)$target['defense'];$multiplier=$action==='raid'?0.70:1.00;
        return ['target'=>$target,'action'=>$action,'turns'=>$turns,'attack_turn_cost'=>$turns,'attacker_force'=>(int)round($attackForce*$multiplier),'defender_force'=>$defenseForce,'expected_loot_cap'=>$action==='raid'?'5% Naquadah':'10% Naquadah','protection_required'=>true,'formula'=>'validated force comparison + technology + defense + deterministic resolver'];
    }
    public function weaponInventory(int $playerId): array {
        if($playerId<1)throw new InvalidArgumentException('Invalid weapon inventory request');
        $tech=$this->pdo->prepare("SELECT COALESCE(MAX(CASE WHEN t.category='offense' THEN pt.level ELSE 0 END),0) offense_level,COALESCE(MAX(CASE WHEN t.category='defense' THEN pt.level ELSE 0 END),0) defense_level FROM player_technologies pt JOIN technologies t ON t.id=pt.technology_id WHERE pt.player_id=?");$tech->execute([$playerId]);$tm=$tech->fetch(PDO::FETCH_ASSOC)?:['offense_level'=>0,'defense_level'=>0];
        $modifier=['attack'=>1+((int)$tm['offense_level']*0.05),'super_attack'=>1+((int)$tm['offense_level']*0.05),'defense'=>1+((int)$tm['defense_level']*0.05),'super_defense'=>1+((int)$tm['defense_level']*0.05),'mothership'=>1+(((int)$tm['offense_level']+(int)$tm['defense_level'])*0.025)];
        $s=$this->pdo->prepare("SELECT pw.id,pw.weapon_type_id,pw.quantity,pw.durability,wt.name,wt.category,wt.power,wt.price,wt.max_durability,wt.description FROM player_weapons pw JOIN weapon_types wt ON wt.id=pw.weapon_type_id WHERE pw.player_id=? ORDER BY wt.category,wt.name");$s->execute([$playerId]);$owned=[];foreach($s->fetchAll(PDO::FETCH_ASSOC) as $row){$condition=$row['max_durability']>0?(int)$row['durability']/(int)$row['max_durability']:0;$row['quantity']=(int)$row['quantity'];$row['durability']=(int)$row['durability'];$row['power']=(int)$row['power'];$row['max_durability']=(int)$row['max_durability'];$row['condition_percent']=(int)round($condition*100);$row['technology_modifier']=round($modifier[$row['category']]??1,2);$row['effective_power']=(int)round($row['power']*$condition*($modifier[$row['category']]??1));$row['readiness']=$row['quantity']>0&&$row['durability']>0?'READY':'UNAVAILABLE';$owned[]=$row;}
        $c=$this->pdo->query("SELECT id,name,category,power,price,max_durability,description FROM weapon_types ORDER BY category,name");$catalogue=$c->fetchAll(PDO::FETCH_ASSOC);foreach($catalogue as &$item){$item['power']=(int)$item['power'];$item['price']=(int)$item['price'];$item['max_durability']=(int)$item['max_durability'];$item['technology_modifier']=round($modifier[$item['category']]??1,2);}unset($item);
        return ['owned'=>$owned,'catalogue'=>$catalogue,'technology_modifier'=>$modifier,'loadout_readiness'=>count(array_filter($owned,static fn(array $w):bool=>$w['readiness']==='READY')),'formula'=>'effective weapon power = base power × condition × technology modifier'];
    }
    public function reportFeed(int $playerId): array {
        if ($playerId < 1) throw new InvalidArgumentException('Invalid report request');
        $rows=[];
        $battle=$this->pdo->prepare("SELECT br.id report_id,'battle' report_kind,br.battle_id entity_id,COALESCE(dp.username,'Unknown Realm') target_name,b.action_type,b.turns_spent,b.loot,b.attacker_casualties,b.defender_casualties,b.winner_id,br.report_text,br.seen_at,br.created_at,CASE WHEN br.seen_at IS NULL THEN 'UNREAD' ELSE 'READ' END read_state,'STANDARD' classification FROM battle_reports br JOIN battles b ON b.id=br.battle_id LEFT JOIN players dp ON dp.id=CASE WHEN b.attacker_id=? THEN b.defender_id ELSE b.attacker_id END WHERE br.recipient_id=? ORDER BY br.created_at DESC LIMIT 25");$battle->execute([$playerId,$playerId]);foreach($battle->fetchAll(PDO::FETCH_ASSOC) as $row){$row['loot']=(int)$row['loot'];$row['turns_spent']=(int)$row['turns_spent'];$row['attacker_casualties']=(int)$row['attacker_casualties'];$row['defender_casualties']=(int)$row['defender_casualties'];$row['title']=$row['target_name'].' — '.(stripos((string)$row['report_text'],'Victory')!==false?'Victory':'Defense held');$rows[]=$row;}
        $intel=$this->pdo->prepare("SELECT ir.id report_id,'intelligence' report_kind,ir.id entity_id,COALESCE(tp.username,'Unknown Realm') target_name,ir.report_type,ir.payload,ir.created_at,ir.seen_at,'CLASSIFIED' classification,CASE WHEN ir.seen_at IS NULL THEN 'UNREAD' ELSE 'READ' END read_state FROM intelligence_reports ir LEFT JOIN players tp ON tp.id=ir.target_player_id WHERE ir.player_id=? ORDER BY ir.created_at DESC LIMIT 25");$intel->execute([$playerId]);foreach($intel->fetchAll(PDO::FETCH_ASSOC) as $row){$row['title']=$row['target_name'].' — '.ucfirst((string)$row['report_type']).' acquired';$row['report_text']='Covert intelligence · detection avoided';$rows[]=$row;}
        usort($rows,static fn(array $a,array $b):int=>strcmp((string)$b['created_at'],(string)$a['created_at']));return $rows;
    }
    public function readReport(int $playerId,string $kind,int $reportId): void {
        if($playerId<1||$reportId<1||!in_array($kind,['battle','intelligence'],true))throw new InvalidArgumentException('Invalid report read request');
        $this->pdo->beginTransaction();try{$updated=$kind==='battle'?$this->pdo->prepare('UPDATE battle_reports SET seen_at=NOW() WHERE id=? AND recipient_id=?'):$this->pdo->prepare('UPDATE intelligence_reports SET seen_at=NOW() WHERE id=? AND player_id=?');$updated->execute([$reportId,$playerId]);if($updated->rowCount()<1&&$kind==='battle')throw new RuntimeException('Report unavailable or ownership check failed');$this->event($playerId,'report_read',$kind,$reportId,['classification'=>$kind==='intelligence'?'CLASSIFIED':'STANDARD']);$this->pdo->commit();}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
    public function covertStats(int $playerId): array {
