        $s=$this->pdo->prepare('SELECT r.spies,r.anti_spies,r.covert_capacity,u.covert_level,u.anti_covert_level FROM player_resources r LEFT JOIN player_unit_stats u ON u.player_id=r.player_id WHERE r.player_id=?');$s->execute([$playerId]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row)throw new RuntimeException('Player covert resources not found');
